#include "dfre/animation.hpp"
#include "animation_head_fixture.hpp"
#include <iostream>
#include <stdexcept>
using U=std::uint32_t;
namespace {
void check(bool n,const char* text){if(!n)throw std::runtime_error(text);}
void store(U& field,U byte,U width,U value){if((width!=1&&width!=2&&width!=4)||byte+width>4)throw std::runtime_error("Invalid scalar span");const U mask=width==4?0xffffffffu:((1u<<(width*8))-1)<<(byte*8);field=(field&~mask)|((value<<(byte*8))&mask);}
}
int main(){try{auto model=animation_head_fixture::model(2,1);dfre::AnimationController c(model);auto view=c.source_state();check(&view.model==&model&&view.animation==&model.animations[0]&&view.frame==&model.animations[0].frames[0],"Current model identities");check(view.pose.data==c.pose().data()&&view.pose_delta.data==c.pose_delta().data()&&view.root_base.data==c.root_positions().data()&&view.root_delta.data==c.root_delta().data(),"Arrays use the existing owner");check(view.bone_count==3&&view.root_count==1&&view.pose.size==3&&view.root_base.size>=view.root_count,"Current counts");view.random_a=0x12345678;store(view.random_a,1,1,0xaa);check(c.random_a()==0x1234aa78,"Byte write reaches current scalar");store(view.random_a,2,2,0xbbcc);check(c.random_a()==0xbbccaa78,"Word write reaches current scalar");store(view.random_a,0,4,0x10203040);check(c.random_a()==0x10203040,"DWORD write reaches current scalar");const U old=view.random_a;bool failed=false;try{store(view.random_a,3,2,0);}catch(const std::exception&){failed=true;}check(failed&&view.random_a==old,"Rejected cross-field write keeps value");view.pose.data[0].angles[0]=91;view.pose_delta.data[0].angles[0]=7;view.root_base.data[0][1]=123;view.root_delta.data[0][1]=19;view.remaining_ticks=5;view.condition_current=7;view.condition_previous=1;view.condition_latched=8;view.accumulator=0xdeadbeef;check(c.frame_ticks()==5&&c.accumulator()==std::int32_t(0xdeadbeef),"Remaining count and accumulator are current");dfre::AnimationInputs inputs;inputs.object_heading=0x20000;inputs.write_random_selector=false;c.tick(inputs);auto next=c.source_state();check(next.pose.data==c.pose().data()&&next.root_base.data==c.root_positions().data(),"Reacquired arrays are current after tick");check(c.pose()[0].angles[0]==98&&c.root_positions()[0][1]==142,"Tick uses the borrowed pose/root values");check(next.remaining_ticks==4&&next.condition_previous==7&&next.condition_latched==14,"Current timer and latch values");check(next.accumulator==0x400,"Driver prefix replaces current accumulator");check(next.random_a==old,"State access keeps random state");std::cout<<"Borrowed state scalar/array identity, widths, timer and driver-prefix checks passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
